#include <bits/stdc++.h>
using namespace std;
char defeats(char y){
    if (y=='R') return 'P';
    if (y=='S') return 'R';
    return 'S';
}
int main(){
    int t; cin >> t;
    for (int tc=0; tc<t; tc++){
        int r,c,n; cin >> r >> c >> n;
        vector<string> g(r);
        for (auto &row : g) cin >> row;
        int dx[]={-1,1,0,0}, dy[]={0,0,-1,1};
        for (int day=0; day<n; day++){
            vector<string> ng = g;
            for (int i=0;i<r;i++) for (int j=0;j<c;j++){
                char need = defeats(g[i][j]);
                bool conquered=false;
                for (int d=0; d<4; d++){
                    int ni=i+dx[d], nj=j+dy[d];
                    if (ni>=0&&ni<r&&nj>=0&&nj<c && g[ni][nj]==need) conquered=true;
                }
                if (conquered) ng[i][j]=need;
            }
            g = ng;
        }
        for (auto &row : g) cout << row << "\n";
        if (tc+1<t) cout << "\n";
    }
}

